/**
 * The database connection and its migration on startup.
 *
 * Migrations generated by drizzle-kit are applied when this module is first
 * imported, so a fresh install and an upgraded one both reach the current
 * schema without a manual step.
 *
 * The file holds other people's private messages, so it is created with mode
 * 600 and its directory with 700, and WAL journalling keeps reads from blocking
 * the single writer.
 *
 * @example
 * ```ts
 * import { db } from "./db.js";
 * import { chats } from "./schema.js";
 *
 * const rows = await db.select().from(chats);
 * ```
 */

import { Database } from "bun:sqlite";
import fs from "node:fs";
import path from "node:path";
import { drizzle } from "drizzle-orm/bun-sqlite";
import { migrate } from "drizzle-orm/bun-sqlite/migrator";
import { DB_PATH } from "../config/index.js";
import { log } from "../lib/logger.js";
import * as schema from "./schema.js";

process.umask(0o077);

const dbPath = path.resolve(DB_PATH);
const dbDir = path.dirname(dbPath);
if (!fs.existsSync(dbDir)) {
  fs.mkdirSync(dbDir, { recursive: true, mode: 0o700 });
}

const sqlite = new Database(dbPath);
sqlite.run("PRAGMA journal_mode = WAL;");

export const db = drizzle(sqlite, { schema });

export const rawDb = sqlite;
export const databaseFile = dbPath;

migrate(db, { migrationsFolder: path.join(import.meta.dir, "../../../drizzle") });

for (const file of [dbPath, `${dbPath}-wal`, `${dbPath}-shm`]) {
  try {
    if (fs.existsSync(file)) fs.chmodSync(file, 0o600);
  } catch {
    log.warn({ file }, "could not restrict database file permissions");
  }
}

export function closeDb(): void {
  sqlite.close();
}
